:root {
  --bg: #1e1e2f;
  --card: #2a2a40;
  --text: #e0e0e0;
  --accent: #4caf50;
  --accent-dark: #388e3c;
  --muted: #8a8a9a;
  --danger: #e53935;
  --radius: 12px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.game-card {
  background: var(--card);
  border-radius: var(--radius);
  padding: 24px;
  width: 100%;
  max-width: 480px;
  display: flex;
  flex-direction: column;
  gap: 16px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
}

header h1 {
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--accent);
  margin-bottom: 4px;
}

.subtitle {
  font-size: 0.95rem;
  color: var(--muted);
  line-height: 1.4;
}

.score-bar {
  display: flex;
  justify-content: space-between;
  font-size: 1.1rem;
  font-weight: 600;
  padding: 8px 0;
  border-bottom: 1px solid var(--muted);
}

#status {
  color: var(--accent);
}

.canvas-wrap {
  position: relative;
  width: 100%;
  aspect-ratio: 1 / 1;
  background: #14141f;
  border-radius: 8px;
  overflow: hidden;
}

canvas {
  display: block;
  width: 100%;
  height: 100%;
  image-rendering: pixelated;
}

.overlay {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 12px;
  background: rgba(20, 20, 31, 0.85);
  padding: 16px;
  text-align: center;
  font-size: 1rem;
  line-height: 1.5;
}

.overlay.hidden {
  display: none;
}

.overlay .hint {
  font-size: 0.85rem;
  color: var(--muted);
}

kbd {
  background: var(--bg);
  border: 1px solid var(--muted);
  border-radius: 4px;
  padding: 2px 6px;
  font-size: 0.85em;
  font-family: inherit;
}

.controls {
  display: flex;
  gap: 12px;
}

button {
  flex: 1;
  font: inherit;
  font-weight: 600;
  padding: 12px 16px;
  border: none;
  border-radius: 8px;
  background: var(--accent);
  color: #fff;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
}

button:hover {
  background: var(--accent-dark);
}

button:focus-visible {
  outline: 3px solid #fff;
  outline-offset: 2px;
}

button:active {
  transform: scale(0.97);
}

button.secondary {
  background: var(--muted);
}

button.secondary:hover {
  background: #6a6a7a;
}

footer p {
  font-size: 0.8rem;
  color: var(--muted);
  text-align: center;
}

@media (max-width: 400px) {
  .game-card {
    padding: 16px;
  }
  header h1 {
    font-size: 1.4rem;
  }
  .subtitle {
    font-size: 0.85rem;
  }
}

const canvas = document.getElementById('game');
const ctx = canvas.getContext('2d');
const scoreEl = document.getElementById('score');
const statusEl = document.getElementById('status');
const overlay = document.getElementById('overlay');
const overlayText = document.getElementById('overlay-text');
const pauseBtn = document.getElementById('pauseBtn');
const restartBtn = document.getElementById('restartBtn');

const GRID = 20;
const CELL = canvas.width / GRID;

let snake, dir, nextDir, food, score, running, gameOver, timer;

function reset() {
  snake = [{ x: 10, y: 10 }];
  dir = { x: 1, y: 0 };
  nextDir = { x: 1, y: 0 };
  score = 0;
  running = false;
  gameOver = false;
  clearInterval(timer);
  timer = null;
  spawnFood();
  updateUI();
  draw();
}

function spawnFood() {
  do {
    food = {
      x: Math.floor(Math.random() * GRID),
      y: Math.floor(Math.random() * GRID)
    };
  } while (snake.some(s => s.x === food.x && s.y === food.y));
}

function updateUI() {
  scoreEl.textContent = score;
  if (gameOver) {
    statusEl.textContent = 'Game Over';
    statusEl.style.color = 'var(--danger)';
    overlayText.innerHTML = `Game Over! Score: ${score}.<br>Press <kbd>R</kbd> or click <strong>Restart</strong>.`;
    overlay.classList.remove('hidden');
    pauseBtn.textContent = 'Play';
    pauseBtn.disabled = true;
  } else if (running) {
    statusEl.textContent = 'Playing';
    statusEl.style.color = 'var(--accent)';
    overlay.classList.add('hidden');
    pauseBtn.textContent = 'Pause';
    pauseBtn.disabled = false;
  } else {
    statusEl.textContent = 'Paused';
    statusEl.style.color = 'var(--muted)';
    overlay.classList.remove('hidden');
    overlayText.innerHTML = 'Press <kbd>Space</kbd> or click <strong>Play</strong> to start.<br><span class="hint">Arrow keys to move. P to pause. R to restart.</span>';
    pauseBtn.textContent = 'Play';
    pauseBtn.disabled = false;
  }
}

function startLoop() {
  clearInterval(timer);
  timer = setInterval(tick, 120);
}

function tick() {
  if (!running || gameOver) return;
  dir = nextDir;
  const head = { x: snake[0].x + dir.x, y: snake[0].y + dir.y };

  if (head.x < 0 || head.x >= GRID || head.y < 0 || head.y >= GRID ||
      snake.some(s => s.x === head.x && s.y === head.y)) {
    gameOver = true;
    running = false;
    clearInterval(timer);
    updateUI();
    draw();
    return;
  }

  snake.unshift(head);

  if (head.x === food.x && head.y === food.y) {
    score++;
    spawnFood();
  } else {
    snake.pop();
  }

  updateUI();
  draw();
}

function draw() {
  ctx.fillStyle = '#14141f';
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  // Food
  ctx.fillStyle = '#e53935';
  ctx.fillRect(food.x * CELL + 2, food.y * CELL + 2, CELL - 4, CELL - 4);

  // Snake
  snake.forEach((s, i) => {
    ctx.fillStyle = i === 0 ? '#4caf50' : '#388e3c';
    ctx.fillRect(s.x * CELL + 1, s.y * CELL + 1, CELL - 2, CELL - 2);
  });
}

function togglePause() {
  if (gameOver) return;
  running = !running;
  if (running) startLoop();
  else clearInterval(timer);
  updateUI();
}

function restart() {
  reset();
}

// Keyboard
window.addEventListener('keydown', (e) => {
  const key = e.key;
  if (['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', ' '].includes(key)) {
    e.preventDefault();
  }

  if (key === ' ' || key === 'Spacebar') {
    togglePause();
    return;
  }
  if (key === 'r' || key === 'R') {
    restart();
    return;
  }
  if (!running) return;

  const map = {
    ArrowUp: { x: 0, y: -1 },
    ArrowDown: { x: 0, y: 1 },
    ArrowLeft: { x: -1, y: 0 },
    ArrowRight: { x: 1, y: 0 }
  };
  const nd = map[key];
  if (nd && !(nd.x === -dir.x && nd.y === -dir.y)) {
    nextDir = nd;
  }
});

pauseBtn.addEventListener('click', togglePause);
restartBtn.addEventListener('click', restart);

// Init
reset();
